"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Card: generated by UIX from the design system. Same variants and sizes as the Figma component.

const cardVariants = cva(
  "flex flex-col gap-4 p-6 text-fg-primary rounded-xl",
  {
    variants: {
      appearance: {
        outlined: "bg-surface border border-line-default",
        elevated: "bg-surface shadow-md",
        filled: "skin-keep bg-subtle",
      },
    },
    defaultVariants: {
      appearance: "outlined",
    },
  },
);

export interface CardProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof cardVariants> {}

const Card = React.forwardRef<HTMLDivElement, CardProps>(
  ({ className, appearance, ...props }, ref) => (
    <div data-slot="card" data-kind="surface" ref={ref} className={cn(cardVariants({ appearance }), className)} {...props} />
  ),
);
Card.displayName = "Card";

const CardMedia = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("w-full overflow-hidden [&>img]:size-full [&>img]:object-cover bg-muted h-[160px] rounded-md", className)} {...props} />
));
CardMedia.displayName = "CardMedia";

const CardHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("flex items-start justify-between gap-3", className)} {...props} />
));
CardHeader.displayName = "CardHeader";

const CardTitle = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(({ className, ...props }, ref) => (
  <h3 ref={ref} className={cn("text-title-large text-fg-primary", className)} {...props} />
));
CardTitle.displayName = "CardTitle";

const CardDescription = React.forwardRef<HTMLParagraphElement, React.HTMLAttributes<HTMLParagraphElement>>(({ className, ...props }, ref) => (
  <p ref={ref} className={cn("text-body-medium text-fg-secondary", className)} {...props} />
));
CardDescription.displayName = "CardDescription";

const CardActions = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("flex items-center gap-2", className)} {...props} />
));
CardActions.displayName = "CardActions";

const CardFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("flex items-center border-t border-line-subtle pt-3 text-body-small text-fg-tertiary", className)} {...props} />
));
CardFooter.displayName = "CardFooter";

export { Card, CardMedia, CardHeader, CardTitle, CardDescription, CardActions, CardFooter, cardVariants };
